import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.LX5S0jbT.js";const p=JSON.parse('{"title":"斜杠命令","description":"","frontmatter":{},"headers":[],"relativePath":"zh/slash-commands.md","filePath":"zh/slash-commands.md"}'),r={name:"zh/slash-commands.md"};function c(l,t,h,i,s,n){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h1><p>在 Pi 的终端编辑器中输入 <code>/</code> 可搜索当前会话可用的命令。本页列出当前 Pi 版本中的内置命令。</p><p>扩展（extension）、提示词模板和技能（skill）都可以添加命令。因此，Pi 中的命令菜单才是你所加载资源的准确参考。</p><h2 id="模型与设置" tabindex="-1">模型与设置 <a class="header-anchor" href="#模型与设置" aria-label="Permalink to &quot;模型与设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/settings</code></td><td>打开设置</td></tr><tr><td><code>/model [provider/model]</code></td><td>选择模型</td></tr><tr><td><code>/thinking [level]</code></td><td>设置思考级别（thinking level）</td></tr><tr><td><code>/scoped-models</code></td><td>配置交互式循环切换使用的模型</td></tr><tr><td><code>/login [provider]</code></td><td>添加提供商（provider）认证</td></tr><tr><td><code>/logout</code></td><td>移除提供商认证</td></tr><tr><td><code>/llama</code></td><td>管理已配置的 llama.cpp 路由器上的模型</td></tr></tbody></table><h2 id="会话与上下文" tabindex="-1">会话与上下文 <a class="header-anchor" href="#会话与上下文" aria-label="Permalink to &quot;会话与上下文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/new</code></td><td>开始新会话</td></tr><tr><td><code>/resume</code></td><td>切换到另一个已保存的会话</td></tr><tr><td><code>/name [name]</code></td><td>设置会话显示名称；省略时显示当前名称</td></tr><tr><td><code>/session</code></td><td>显示当前会话信息和统计</td></tr><tr><td><code>/tree</code></td><td>浏览会话树</td></tr><tr><td><code>/fork</code></td><td>从较早的用户消息创建新会话</td></tr><tr><td><code>/clone</code></td><td>在当前位置复制当前会话</td></tr><tr><td><code>/compact [instructions]</code></td><td>压缩当前上下文，可附加自定义指令</td></tr><tr><td><code>/import &lt;path&gt;</code></td><td>导入并恢复 JSONL 会话</td></tr></tbody></table><h2 id="导出与分享" tabindex="-1">导出与分享 <a class="header-anchor" href="#导出与分享" aria-label="Permalink to &quot;导出与分享&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/copy</code></td><td>复制最后一条助手消息</td></tr><tr><td><code>/export [path]</code></td><td>将会话导出为 HTML 或 JSONL</td></tr><tr><td><code>/share</code></td><td>上传会话并返回查看链接</td></tr><tr><td><code>/bug [description]</code></td><td>为 Pi 开发者准备私密的 bug 报告</td></tr></tbody></table><p>导出或分享之前请先检查会话内容。会话可能包含提示词、工具参数、命令输出、文件内容，以及对话中暴露的凭据。</p><h2 id="运行时与项目" tabindex="-1">运行时与项目 <a class="header-anchor" href="#运行时与项目" aria-label="Permalink to &quot;运行时与项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/trust</code></td><td>保存项目信任决定，供未来的 Pi 进程使用</td></tr><tr><td><code>/mcp</code></td><td>管理 MCP 服务器：登录、重连、启用或禁用、更改暴露范围</td></tr><tr><td><code>/reload</code></td><td>重新加载快捷键、扩展、技能、模板、主题和上下文文件</td></tr><tr><td><code>/hotkeys</code></td><td>显示当前生效的快捷键</td></tr><tr><td><code>/changelog</code></td><td>显示更新日志条目</td></tr><tr><td><code>/quit</code></td><td>退出 Pi</td></tr></tbody></table><h2 id="资源添加的命令" tabindex="-1">资源添加的命令 <a class="header-anchor" href="#资源添加的命令" aria-label="Permalink to &quot;资源添加的命令&quot;">​</a></h2><ul><li>扩展可以注册带自定义参数和补全行为的命令。</li><li>每个提示词模板以其模板名可用。</li><li>技能在启用技能命令时以 <code>/skill:name</code> 形式可用。</li></ul><p>添加或更改可发现的命令资源后使用 <code>/reload</code>。加载和命名规则见<a href="./extensions.html">扩展</a>、<a href="./prompt-templates.html">提示词模板</a>和<a href="./skills.html">技能</a>。</p>',15)])])}const b=d(r,[["render",c]]);export{p as __pageData,b as default};
